window.kbPageData["views/entry/k-9410efcb3b355d87"] = {"key":"entry/k-9410efcb3b355d87","state":{"route":"entry/k-9410efcb3b355d87"},"node":{"id":"k-9410efcb3b355d87","mode":"k","title":"“景德镇手工瓷业遗存”列入《世界遗产名录》（7 月 25 日）","type":"事实与事件","domain":"文化","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["culture"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["文化"],"时间索引":["年度事件或数据"],"来源主题":["重要事件"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"“景德镇手工瓷业遗存”列入《世界遗产名录》（7 月 25 日）","slug":"013f0c06f81b"}],"directorySummary":"考点十五 “景德镇手工瓷业遗存”列入《世界遗产名录》（7 月 25 日）\n2026 年 7 月 25 日，在韩国釜山召开的联合国教科文组织第 48 届世界遗产大会上，中国提交\n的“景德镇手工瓷业遗存”项目通过审议，成功列入《世界遗产名录》，至此中国世界遗产总\n数达 61 项。该遗存完整保存了 10 …","sources":[{"id":"d8a10c16eab04e32","label":"“景德镇手工瓷业遗存”列入《世界遗产名录》（7 月 25 日）","topic":"重要事件","category":"时政","text":"考点十五 “景德镇手工瓷业遗存”列入《世界遗产名录》（7 月 25 日）\n2026 年 7 月 25 日，在韩国釜山召开的联合国教科文组织第 48 届世界遗产大会上，中国提交\n的“景德镇手工瓷业遗存”项目通过审议，成功列入《世界遗产名录》，至此中国世界遗产总\n数达 61 项。该遗存完整保存了 10 至 19 世纪手工制瓷技术体系和产业组织形态，包含原料开\n采、燃料供应、生产加工、水运物流等全产业链设施，体现了世界对中国瓷器的认可。\n此次申遗成功，填补了《世界遗产名录》中“瓷”主题遗产的空白，标志着中国古代丝绸、\n茶、瓷三大文化载体在世界遗产领域实现了完整呈现。","source":{"doc":"4e539a366dce19555ccf","first":26,"last":26,"page":26,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"culture","title":"文化传承与创新表达"}],"units":{"k-9410efcb3b355d87":[]}};
